theorem comp_assoc {S : Type*} [AddCommGroup S] [Module ℚ S] [Module.Finite ℚ S]
    {hV : QHodgeStructure n V} {hW : QHodgeStructure n W}
    {hU : QHodgeStructure n U} {hS : QHodgeStructure n S}
    (h : HodgeHom hU hS) (g : HodgeHom hW hU) (f : HodgeHom hV hW) :
    (h.comp g).comp f = h.comp (g.comp f)

@[simp] theorem comp_toLinearMap {hV : QHodgeStructure n V}
    {hW : QHodgeStructure n W} {hU : QHodgeStructure n U}
    (g : HodgeHom hW hU) (f : HodgeHom hV hW) :
    (g.comp f).toLinearMap = g.toLinearMap.comp f.toLinearMap

@[simp] theorem comp_toLinearMap {X Y Z : HodgeStructCat n}
    (f : X ⟶ Y) (g : Y ⟶ Z) :
    (f ≫ g).toLinearMap = g.toLinearMap.comp f.toLinearMap

@[ext]
theorem hom_ext {X Y : HodgeStructCat.{u} n} {f g : X ⟶ Y}
    (h : f.toLinearMap = g.toLinearMap) : f = g

theorem IsMinimalNonmember.independent {x₁ x₂ : α}
    (h₁ : IsMinimalNonmember R C x₁) (h₂ : IsMinimalNonmember R C x₂) :
    ¬ Relation.TransGen R x₁ x₂ ∧ ¬ Relation.TransGen R x₂ x₁

theorem IsMinimalNonmember.not_transGen {x₁ x₂ : α}
    (h₁ : IsMinimalNonmember R C x₁) (h₂ : IsMinimalNonmember R C x₂) :
    ¬ Relation.TransGen R x₁ x₂

theorem isFlasque_of_retract {F G : TopCat.Sheaf AddCommGrpCat.{u} X}
    (ι : F ⟶ G) (r : G ⟶ F) (hri : ι ≫ r = 𝟙 F) [G.IsFlasque] :
    F.IsFlasque

theorem cohomology_congr_of_homotopy {X Y : TopCat.{0}} {f g : X ⟶ Y}
    (H : TopCat.Homotopy f g) (n : ℕ) :
    (singularCohomologyFunctor n).map f.op = (singularCohomologyFunctor n).map g.op

lemma firstVertex_map {V U : TopCat.{0}} (f : V ⟶ U) {n : ℕ}
    (σ : (TopCat.toSSet.obj V) _⦋n⦌) :
    firstVertex ((TopCat.toSSet.map f).app (op ⦋n⦌) σ) = f.hom (firstVertex σ)

lemma app_injective_of_mono {X : TopCat.{0}} {K B : TopCat.Sheaf AddCommGrpCat.{0} X}
    (f : K ⟶ B) [Mono f] (U : Opens X) :
    Function.Injective (f.hom.app (op U))

lemma comp_app_apply_eq_zero {X : TopCat.{0}} {F G H : TopCat.Sheaf AddCommGrpCat.{0} X}
    (f : F ⟶ G) (g : G ⟶ H) (hfg : f ≫ g = 0) (U : Opens X) (s : F.1.obj (op U)) :
    g.hom.app (op U) (f.hom.app (op U) s) = 0

lemma existsUnique_section_preimage {X : TopCat.{0}}
    {K B R : TopCat.Sheaf AddCommGrpCat.{0} X}
    (f : K ⟶ B) (g : B ⟶ R) (hfg : f ≫ g = 0)
    (hexact : (ShortComplex.mk f g hfg).ShortExact)
    (U : Opens X) (t : B.1.obj (op U)) (ht : g.hom.app (op U) t = 0) :
    ∃! δ : K.1.obj (op U), f.hom.app (op U) δ = t

lemma ambient_pushSimplex {U W : Opens X} (i : U ⟶ W) {n : ℕ}
    (σ : (TopCat.toSSet.obj ((Opens.toTopCat X).obj U)) _⦋n⦌) (p) :
    ambient ((pushSimplex i σ).down.hom p) = ambient (σ.down.hom p)

lemma pushSimplex_corestrict {W : Opens X} {n : ℕ}
    (σ : (TopCat.toSSet.obj ((Opens.toTopCat X).obj W)) _⦋n⦌) {U : Opens X}
    (h : SimplexIn σ U) (hUW : U ≤ W) :
    pushSimplex (homOfLE hUW) (corestrict σ h) = σ

@[simp] theorem toComodHom_comp {M N P : ComodCat.{v} R A}
    (f : M ⟶ N) (g : N ⟶ P) :
    (f ≫ g).toComodHom = g.toComodHom.comp f.toComodHom

@[ext]
lemma hom_ext {M N : FComodCat.{v} R A} {f g : M ⟶ N}
    (h : f.hom.toComodHom = g.hom.toComodHom) : f = g

lemma finite_support_of_isNoetherian {X : Scheme.{u}}
    [AlgebraicGeometry.IsNoetherian X] [Zero R] (c : Cycle X R) :
    (Function.support ⇑c).Finite

lemma map_mem_cyclesOfDim (f : X ⟶ Y) [IsClosedImmersion f] {d : ℕ∞}
    {c : Scheme.Cycle X ℤ} (hc : c ∈ cyclesOfDim X d) :
    map f c ∈ cyclesOfDim Y d

lemma single_mem_cyclesOfCodim {X : Scheme.{u}} {x : X} {p : ℕ∞}
    (h : codim x = p) (n : ℤ) :
    Cycle.single x n ∈ cyclesOfCodim X p

lemma single_mem_cyclesOfDim {X : Scheme.{u}} {x : X} {d : ℕ∞}
    (h : dimClosure x = d) (n : ℤ) :
    Cycle.single x n ∈ cyclesOfDim X d

theorem isInternal_of_eq_bot {A : ι → Submodule R M} {i₀ : ι}
    (hbot : ∀ i, i ≠ i₀ → A i = ⊥) (htop : A i₀ = ⊤) :
    DirectSum.IsInternal A

theorem analyticOnNhd_sectionExtend {U : Opens (Fin n → ℂ)}
    (f : (holomorphicSheaf n).presheaf.obj (op U)) :
    AnalyticOnNhd ℂ (sectionExtend f) (U : Set (Fin n → ℂ))

lemma holomorphicSheaf.contMDiff_section {U : (Opens (TopCat.of (Fin n → ℂ)))ᵒᵖ}
    (f : (holomorphicSheaf n).presheaf.obj U) :
    ContMDiff 𝓘(ℂ, Fin n → ℂ) 𝓘(ℂ) ω f.1

@[simp] lemma map_constSection {U V : (Opens (TopCat.of (Fin n → ℂ)))ᵒᵖ}
    (i : U ⟶ V) (c : ℂ) :
    (holomorphicSheaf n).presheaf.map i (constSection n U c) = constSection n V c

@[simp] lemma sectionExtend_apply_of_mem {U : Opens (Fin n → ℂ)}
    (f : (holomorphicSheaf n).presheaf.obj (op U)) {y : Fin n → ℂ} (hy : y ∈ U) :
    sectionExtend f y = f.1 ⟨y, hy⟩

theorem norm_torusMap_apply_sub_center {n : ℕ} (c : Fin n → ℂ) {R : Fin n → ℝ}
    {i : Fin n} (hR : 0 ≤ R i) (θ : Fin n → ℝ) :
    ‖torusMap c R θ i - c i‖ = R i

theorem torusMap_mem_closedPolydisc {n : ℕ} {c : Fin n → ℂ} {R : Fin n → ℝ}
    (hR : ∀ i, 0 ≤ R i) (θ : Fin n → ℝ) :
    torusMap c R θ ∈ closedPolydisc c R

theorem torusMap_sub_ne_zero {n : ℕ} {c z : Fin n → ℂ} {R : Fin n → ℝ}
    (hz : z ∈ polydisc c R) (θ : Fin n → ℝ) (i : Fin n) :
    torusMap c R θ i - z i ≠ 0

theorem analyticAt_of_mem_polydisc [CompleteSpace E] {f : (Fin n → ℂ) → E}
    {c z : Fin n → ℂ} {R : Fin n → ℝ}
    (hf : DifferentiableOn ℂ f (closedPolydisc c R)) (hz : z ∈ polydisc c R) :
    AnalyticAt ℂ f z

theorem analyticOnNhd_polydisc [CompleteSpace E] {f : (Fin n → ℂ) → E}
    {c : Fin n → ℂ} {R : Fin n → ℝ}
    (hf : DifferentiableOn ℂ f (closedPolydisc c R)) :
    AnalyticOnNhd ℂ f (polydisc c R)

theorem update_mem_closedPolydisc {c w : Fin n → ℂ} {R : Fin n → ℝ}
    (hw : w ∈ closedPolydisc c R) {i : Fin n} {t : ℂ}
    (ht : t ∈ closedBall (c i) (R i)) :
    Function.update w i t ∈ closedPolydisc c R

theorem analyticOnNhd_of_differentiableOn [CompleteSpace F] {f : (Fin n → ℂ) → F}
    {s : Set (Fin n → ℂ)} (hs : IsOpen s) (hf : DifferentiableOn ℂ f s) :
    AnalyticOnNhd ℂ f s

theorem const_of_extDeriv_eq_zero_ball {x : Fin n → ℂ} {r : ℝ}
    {g : (Fin n → ℂ) → ((Fin n → ℂ) [⋀^Fin 0]→L[ℂ] F)}
    (hg : AnalyticOnNhd ℂ g (ball x r))
    (hd : ∀ y ∈ ball x r, extDeriv g y = 0) :
    ∀ y ∈ ball x r, ∀ z ∈ ball x r, g y = g z
